import React, { useState } from "react";
import toast from "react-hot-toast";
import {
  User,
  MapPin,
  Phone,
  Calendar,
  Camera,
  FileText,
  ShieldCheck,
  Loader2,
  Navigation,
} from "lucide-react";

export default function WajibLaporForm() {
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    nama: "",
    alamat: "",
    whatsapp: "",
    tanggal: "",
    kasus: "",
    namaPk: "",
    nomorPk: "",
    alasan: "",
    // foto: null,
    latitude: "",
    longitude: "",
    maps: "",
  });

  const kasusList = [
    "Dalam Jabatan",
    "Ekonomi",
    "ITE",
    "KDRT",
    "Kenakalan",
    "Korupsi",
    "Kesusilaan",
    "Mata Uang",
    "Memalsukan Materai/Surat",
    "Memeras/Mengancam",
    "Money Laundering/TPPU",
    "Merusak Barang",
    "Narkotika",
    "Pembakaran",
    "Pembunuhan",
    "Penadahan",
    "Penganiayaan",
    "Penggelapan",
    "Penipuan",
    "Penculikan",
    "Pencurian",
    "Penyuapan",
    "Penyeludupan",
    "Perjudian",
    "Perikanan",
    "Perlindungan Anak",
    "Perampokan",
    "Politik",
    "Pornografi",
    "Subversi",
    "Terhadap Kepala Negara",
    "Terhadap Ketertiban",
    "Teroris",
    "Trafficking",
    "Yang lain",
  ];

  const pkList = [
    "ANANDA SEPTIANA LESTARI,S.Tr.Pas",
    "BADRUS",
    "BAIQ EFY MUFIDAH, A.Ma.",
    "CAHYA SULISTYANINGSIH, S.P., M.Si.",
    "DESY WULANDARI S.H.",
    "DEWA MADE YUDIK ARDIANTIKA,S.H.",
    "DONO BUDIARSO, S.Pt.",
    "FATHUL ANWAR HIDAYATULLAH,S.Psi.",
    "FIRMAN AKBARA.Md.",
    "I PANDE KETUT ARYA YARSITA,S.H.",
    "I WAYAN SUDIARTHA",
    "IKA INDAYANI, SH.",
    "INDRA RUKMA HISON SAFI I, S.H.",
    "JERY AGUS PRATAMA,SH.",
    "M. ARVIN, S.H.",
    "NAOVAL YUSFI MUTTAQIN, S.Psi., M.Sc.",
    "NI MADE DWI SURYANINGSIH, S.H.",
    "NIKEN RACHMAWATI, S.Tr.Pas",
    "NOVA TIKA UDAYANI, S.H.",
    "NOVAN RIZKI RAMADAN, S.Tr.Pas",
    "NURLAILAH,S.S.T.",
    "REGINA IBRAHIM, S.Tr.Pas",
    "RIZKY MILENIA,S.Tr.Pas",
    "SAHABUDIN",
    "SITI NURAHLIN, S.H.",
    "SITI RUTMAWATI, S.Sos.",
    "SONI HIDAYAT",
    "SUDRAJAT TRIWANDOKO,S.Psi.",
    "TRI KUMALASARI,A.Md.Kom.,SH.",
    "UNWANUL KHALISH, S.H.",
    "URBAN MURDANIL, S.Tr.Pas",
    "ZAINUL ASHADI PUTRA, S.Psi.",
  ];

  const handleChange = (e) => {
    const { name, value, files } = e.target;

    if (files) {
      setFormData({
        ...formData,
        [name]: files[0],
      });
    } else {
      setFormData({
        ...formData,
        [name]: value,
      });
    }
  };

  const getLocation = () => {
    if (!navigator.geolocation) {
      toast.error("Browser tidak mendukung GPS");
      return;
    }

    toast.loading("Mengambil lokasi...");

    navigator.geolocation.getCurrentPosition(
      (position) => {
        toast.dismiss();

        const lat = position.coords.latitude;
        const lng = position.coords.longitude;

        setFormData((prev) => ({
          ...prev,
          latitude: lat,
          longitude: lng,
          maps: `https://maps.google.com/?q=${lat},${lng}`,
        }));

        toast.success("Lokasi berhasil didapatkan");
      },
      () => {
        toast.dismiss();
        toast.error("Gagal mendapatkan lokasi");
      },
    );
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.latitude) {
      toast.error("Silakan ambil lokasi terlebih dahulu");
      return;
    }

    setLoading(true);

    try {
      await fetch(
        "https://script.google.com/macros/s/AKfycbxngxLle_CBejptiQXS0yzow2qmX1-Qgx4QqlVnWuL8OCI5CL7MAOYl9O5hIoZmwnxs/exec",
        {
          method: "POST",
          mode: "no-cors",
          headers: {
            "Content-Type": "application/x-www-form-urlencoded",
          },
          body: new URLSearchParams(formData).toString(),
        },
      );

      toast.success("Wajib lapor berhasil dikirim");
    } catch (error) {
      console.error(error);

      toast.error("Terjadi kesalahan");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f3f0ff] py-10 px-4">
      <div className="mx-auto max-w-4xl">
        <div className="overflow-hidden rounded-2xl border bg-white shadow-lg">
          <div className="h-3 bg-indigo-600" />

          <div className="border-b p-6">
            <div className="mb-3 flex items-center gap-3">
              <ShieldCheck className="h-8 w-8 text-indigo-600" />

              <div>
                <h1 className="text-3xl font-bold text-gray-800">
                  WAJIB LAPOR KLIEN
                </h1>

                <p className="mt-1 text-sm text-gray-500">
                  Form wajib lapor klien Bapas Mataram
                </p>
              </div>
            </div>

            <div className="rounded-xl bg-indigo-50 p-4 text-sm text-gray-700">
              Pastikan data yang diisi benar dan lokasi GPS aktif saat melakukan
              wajib lapor.
            </div>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6 p-6">
            {/* Nama */}
            <div className="rounded-2xl border p-5">
              <label className="mb-2 flex items-center gap-2 font-semibold">
                <User size={18} />
                Nama
              </label>

              <input
                type="text"
                name="nama"
                required
                value={formData.nama}
                onChange={handleChange}
                className="w-full rounded-xl border p-3 outline-none focus:border-indigo-500"
                placeholder="Masukkan nama"
              />
            </div>

            {/* Alamat */}
            <div className="rounded-2xl border p-5">
              <label className="mb-2 flex items-center gap-2 font-semibold">
                <MapPin size={18} />
                Alamat
              </label>

              <textarea
                name="alamat"
                required
                value={formData.alamat}
                onChange={handleChange}
                className="min-h-[120px] w-full rounded-xl border p-3 outline-none focus:border-indigo-500"
                placeholder="Masukkan alamat"
              />
            </div>

            {/* WA */}
            <div className="rounded-2xl border p-5">
              <label className="mb-2 flex items-center gap-2 font-semibold">
                <Phone size={18} />
                Nomor WhatsApp
              </label>

              <input
                type="tel"
                name="whatsapp"
                required
                value={formData.whatsapp}
                onChange={handleChange}
                className="w-full rounded-xl border p-3 outline-none focus:border-indigo-500"
                placeholder="08xxxxxxxxxx"
              />
            </div>

            {/* Tanggal */}
            <div className="rounded-2xl border p-5">
              <label className="mb-2 flex items-center gap-2 font-semibold">
                <Calendar size={18} />
                Tanggal Wajib Lapor
              </label>

              <input
                type="date"
                name="tanggal"
                required
                value={formData.tanggal}
                onChange={handleChange}
                className="w-full rounded-xl border p-3 outline-none focus:border-indigo-500"
              />
            </div>

            {/* Kasus */}
            <div className="rounded-2xl border p-5">
              <label className="mb-4 flex items-center gap-2 font-semibold">
                <FileText size={18} />
                Kasus
              </label>

              <div className="grid gap-3 md:grid-cols-2">
                {kasusList.map((item) => (
                  <label
                    key={item}
                    className="flex cursor-pointer items-center gap-3 rounded-xl border p-3 hover:bg-gray-50"
                  >
                    <input
                      type="radio"
                      name="kasus"
                      value={item}
                      checked={formData.kasus === item}
                      onChange={handleChange}
                    />

                    <span>{item}</span>
                  </label>
                ))}
              </div>
            </div>

            {/* Nama PK */}
            <div className="rounded-2xl border p-5">
              <label className="mb-4 flex items-center gap-2 font-semibold">
                <User size={18} />
                Nama PK
              </label>

              <div className="grid gap-3 md:grid-cols-2">
                {pkList.map((item) => (
                  <label
                    key={item}
                    className="flex cursor-pointer items-center gap-3 rounded-xl border p-3 hover:bg-gray-50"
                  >
                    <input
                      type="radio"
                      name="namaPk"
                      value={item}
                      checked={formData.namaPk === item}
                      onChange={handleChange}
                    />

                    <span>{item}</span>
                  </label>
                ))}
              </div>
            </div>

            {/* Nomor PK */}
            <div className="rounded-2xl border p-5">
              <label className="mb-2 font-semibold">Nomor PK</label>

              <input
                type="text"
                name="nomorPk"
                required
                value={formData.nomorPk}
                onChange={handleChange}
                className="w-full rounded-xl border p-3 outline-none focus:border-indigo-500"
                placeholder="Masukkan nomor PK"
              />
            </div>

            {/* Alasan */}
            <div className="rounded-2xl border p-5">
              <label className="mb-2 font-semibold">
                Alasan Tidak Dapat Hadir
              </label>

              <textarea
                name="alasan"
                required
                value={formData.alasan}
                onChange={handleChange}
                className="min-h-[120px] w-full rounded-xl border p-3 outline-none focus:border-indigo-500"
                placeholder="Masukkan alasan"
              />
            </div>

            {/* Lokasi */}
            <div className="rounded-2xl border p-5">
              <div className="mb-4 flex items-center justify-between">
                <div>
                  <h2 className="font-semibold">Lokasi GPS</h2>

                  <p className="text-sm text-gray-500">Ambil lokasi otomatis</p>
                </div>

                <button
                  type="button"
                  onClick={getLocation}
                  className="flex items-center gap-2 rounded-xl bg-indigo-600 px-4 py-2 text-white"
                >
                  <Navigation size={18} />
                  Ambil Lokasi
                </button>
              </div>

              {formData.latitude && (
                <div className="rounded-xl bg-green-50 p-4 text-sm">
                  <p>Latitude: {formData.latitude}</p>
                  <p>Longitude: {formData.longitude}</p>

                  <a
                    href={formData.maps}
                    target="_blank"
                    className="mt-2 inline-block text-indigo-600 underline"
                  >
                    Buka di Google Maps
                  </a>
                </div>
              )}
            </div>

            {/* Upload */}
            <div className="rounded-2xl border p-5">
              <label className="mb-2 flex items-center gap-2 font-semibold">
                <Camera size={18} />
                Foto Kegiatan Klien
              </label>

              <input
                type="file"
                name="foto"
                accept="image/*"
                capture="environment"
                required
                onChange={handleChange}
                className="w-full rounded-xl border p-3"
              />

              <p className="mt-2 text-sm text-gray-500">
                Foto akan langsung diambil dari kamera
              </p>
            </div>

            {/* Submit */}
            <button
              type="submit"
              disabled={loading}
              className="flex w-full items-center justify-center gap-2 rounded-2xl bg-indigo-600 px-6 py-4 font-semibold text-white transition hover:bg-indigo-700"
            >
              {loading ? (
                <>
                  <Loader2 className="animate-spin" size={20} />
                  Mengirim...
                </>
              ) : (
                "Kirim Wajib Lapor"
              )}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}
